"""Engineering control for the straight green case family.

This controller creates a controlled trajectory contrast. Its conflict-zone
policy is conservative engineering, not a statutory right-of-way adjudication.
"""
from __future__ import annotations
from math import hypot

class ControlError(ValueError):
    pass

def command(site, observation, policy):
    if policy not in ('proceed_when_clear','yield_to_present'):
        raise ControlError('unknown policy')
    if observation.get('official_head_id') != site['official_head_id'] or observation.get('facing_approach_id') != site['ego_approach_id']:
        raise ControlError('unbound governing signal')
    if observation.get('lit_aspects') != ['circular_green']:
        raise ControlError('sole circular green not observed')
    if observation.get('frame') is None or observation.get('ego_xy') is None:
        raise ControlError('original frame and ego pose required')
    stop=site['stop_line_xy']
    xy=observation['ego_xy']
    distance=hypot(xy[0]-stop[0],xy[1]-stop[1])
    if distance > site['approach_control_radius_m']:
        return {'throttle':site['approach_throttle'],'brake':0.0,'target':'approach','frame':observation['frame']}
    conflicts=observation.get('other_users')
    if not isinstance(conflicts,list):
        raise ControlError('original other-user packet required')
    occupied=any(u.get('region') in ('intersection','adjacent_crosswalk') for u in conflicts)
    if policy=='yield_to_present' and occupied:
        return {'throttle':0.0,'brake':site['yield_brake'],'target':'hold_before_entry','frame':observation['frame']}
    return {'throttle':site['proceed_throttle'],'brake':0.0,'target':'straight_route','frame':observation['frame']}

"""CARLA-lazy four-view original camera recorder for straight-green attempts."""
from __future__ import annotations

import hashlib
import io
import subprocess
from pathlib import Path
from queue import Empty, Queue

from PIL import Image

from delivery_audit import PRODUCTION_PROFILE, VIEWS


class OriginalCameraRecorder:
    def __init__(self, sensors: dict, scratch: Path, *,
                 profile: dict = PRODUCTION_PROFILE, expected_frames: int = 900,
                 diagnostic_fixture: bool = False, timeout_s: float = 5.0):
        if set(sensors) != set(VIEWS) or set(profile) != set(VIEWS):
            raise ValueError('four original camera sensors and profile required')
        if profile != PRODUCTION_PROFILE and not diagnostic_fixture:
            raise ValueError('profile override requires diagnostic fixture')
        if expected_frames < 2 or timeout_s <= 0:
            raise ValueError('valid original frame count and timeout required')
        self.sensors = sensors
        self.profile = profile
        self.expected_frames = expected_frames
        self.timeout_s = timeout_s
        self.scratch = Path(scratch)
        if not self.scratch.is_dir() or any((self.scratch / view).exists() for view in VIEWS):
            raise ValueError('fresh camera scratch directory required')
        self.queues = {view: Queue(maxsize=expected_frames + 2) for view in VIEWS}
        self.count = 0
        self.closed = False
        for view in VIEWS:
            (self.scratch / view).mkdir()
            sensors[view].listen(lambda image, view=view: self.queues[view].put_nowait(image))

    def read(self, snapshot) -> dict:
        if self.closed or self.count >= self.expected_frames:
            raise ValueError('original camera recorder closed or complete')
        frame = snapshot.frame
        pending = {}
        for view in VIEWS:
            try:
                image = self.queues[view].get(timeout=self.timeout_s)
            except Empty as exc:
                raise ValueError('original camera callback missing: ' + view) from exc
            width, height = self.profile[view]
            if image.frame != frame or image.width != width or image.height != height:
                raise ValueError('original camera frame or dimensions differ: ' + view)
            raw = bytes(image.raw_data)
            if len(raw) != width * height * 4:
                raise ValueError('original camera BGRA buffer differs: ' + view)
            output = io.BytesIO()
            Image.frombytes('RGBA', (width, height), raw, 'raw', 'BGRA').convert('RGB').save(
                output, format='PNG')
            pending[view] = output.getvalue()
        for view, image_bytes in pending.items():
            (self.scratch / view / f'{self.count:06d}.png').write_bytes(image_bytes)
        self.count += 1
        return {view: frame for view in VIEWS}

    def finish(self, output: Path) -> dict:
        """Encode four lossless 20 Hz originals; return attempt-relative seals."""
        if self.closed or self.count != self.expected_frames:
            raise ValueError('complete original camera callbacks required')
        output = Path(output)
        if not output.is_dir() or any((output / f'{view}.mkv').exists() for view in VIEWS):
            raise ValueError('fresh original camera output required')
        refs = {}
        created = []
        try:
            for view in VIEWS:
                path = output / f'{view}.mkv'
                result = subprocess.run(
                    ['ffmpeg', '-v', 'error', '-xerror', '-framerate', '20',
                     '-i', str(self.scratch / view / '%06d.png'),
                     '-frames:v', str(self.expected_frames), '-c:v', 'ffv1',
                     '-level', '3', str(path)], capture_output=True, text=True)
                if result.returncode or not path.is_file() or path.stat().st_size == 0:
                    raise ValueError('original camera lossless encode failed: ' + view + ' ' + result.stderr[-200:])
                created.append(path)
                refs[view] = {'path': path.name,
                              'sha256': hashlib.sha256(path.read_bytes()).hexdigest()}
            return refs
        except Exception:
            for path in created:
                path.unlink(missing_ok=True)
            raise

    def close(self) -> None:
        if not self.closed:
            self.closed = True
            for sensor in self.sensors.values():
                sensor.stop()

"""Independent exact-case comparison over source-measured attempt summaries."""
PAIRS={
 'intersection_vehicle_yield':('green_clear','green_vehicle_present',None,'intersection'),
 'crosswalk_pedestrian_yield':('green_clear','green_pedestrian_present',None,'adjacent_crosswalk'),
 'exhibition_time_qualification':('green_pedestrian_present','green_pedestrian_late','adjacent_crosswalk','outside'),
}
class ComparisonError(ValueError):
    pass

def audit_pair(name,left,right):
    if name not in PAIRS:
        raise ComparisonError('unknown comparison')
    ls,rs,lreg,rreg=PAIRS[name]
    if (left.get('case_suffix'),right.get('case_suffix'))!=(ls,rs):
        raise ComparisonError('wrong exact case pair')
    fixed=('map_sha256','signal_source_sha256','route_source_sha256','crosswalk_source_sha256','camera_profile_sha256','duration_frames','official_head_id','ego_approach_id')
    for key in fixed:
        if not left.get(key) or left[key]!=right.get(key):
            raise ComparisonError('fixed condition differs: '+key)
    for record,region in ((left,lreg),(right,rreg)):
        if record.get('green_frames')!=record['duration_frames']:
            raise ComparisonError('circular green alone not evidenced throughout')
        exhibition=record.get('exhibition')
        if not exhibition or not isinstance(exhibition.get('other_users'),list):
            raise ComparisonError('original exhibition user positions missing')
        regions=[p['region'] for p in exhibition['other_users']]
        if region is None and regions:
            raise ComparisonError('clear baseline occupied at exhibition')
        if region is not None and regions!=[region]:
            raise ComparisonError('other user region at exhibition differs')
        if record.get('lawful_presence_verdict') is not None or record.get('right_of_way_verdict') is not None:
            raise ComparisonError('unsupported legal verdict supplied')
    return {'comparison_id':name,'fixed_conditions_checked':len(fixed),'exhibition_checked':True,'physical_acceptance':False,'legal_verdict':None}
